import itertools

def calculate_A(a_list):
    n = len(a_list)
    A = 0
    for x in range(n):
        prod = 1
        for y in range(n):
            if x == y:
                continue
            prod *= (a_list[x] * a_list[y] - 1) / (a_list[x] - a_list[y])
        A += prod
    return A

